/**
 * Procedural draped-satin texture.
 *
 * Two layers of turbulence (large billows + medium folds) are lit with
 * diffuse + specular lighting, then tinted to warm ivory. The SVG is drawn
 * once at low resolution into a canvas; the browser's smooth upscaling
 * removes the banding that 8-bit noise produces at full size, and the
 * result is cheap to display.
 *
 * No images are generated by AI or downloaded - this is pure SVG maths.
 */

const VIEW_W = 1600;

export const FABRIC_TONES = {
  ivory: { gain: 0.5, base: [0.52, 0.46, 0.4] },
  blush: { gain: 0.46, base: [0.56, 0.4, 0.36] },
};

export function fabricSVG(pxW, pxH, { seed = 3, rotate = -26, relief = 115, tone = "ivory" } = {}) {
  const { gain, base } = FABRIC_TONES[tone] || FABRIC_TONES.ivory;
  const viewH = Math.round((VIEW_W * pxH) / pxW);
  // Lighting is computed per rendered pixel, so scale the relief with resolution.
  const k = pxW / VIEW_W;
  relief = relief * k;
  const [r, g, b] = base;
  const tint = `${gain} 0 0 0 ${r}  ${gain * 1.05} 0 0 0 ${g}  ${gain * 1.08} 0 0 0 ${b}  0 0 0 1 0`;
  const cx = VIEW_W / 2;
  const cy = viewH / 2;
  const span = Math.max(VIEW_W, viewH) * 2;

  return `<svg xmlns="http://www.w3.org/2000/svg" width="${pxW}" height="${pxH}" viewBox="0 0 ${VIEW_W} ${viewH}" preserveAspectRatio="none">
<filter id="f" x="0" y="0" width="100%" height="100%" color-interpolation-filters="sRGB">
<feTurbulence type="fractalNoise" baseFrequency="0.00045 0.0016" numOctaves="1" seed="${seed}" result="big"/>
<feTurbulence type="fractalNoise" baseFrequency="0.0012 0.0045" numOctaves="1" seed="${seed + 7}" result="mid"/>
<feComposite in="big" in2="mid" operator="arithmetic" k2=".7" k3=".45" result="n"/>
<feGaussianBlur in="n" stdDeviation="14" result="nb"/>
<feDiffuseLighting in="nb" surfaceScale="${relief}" result="d"><feDistantLight azimuth="235" elevation="44"/></feDiffuseLighting>
<feSpecularLighting in="nb" surfaceScale="${relief}" specularConstant=".55" specularExponent="26" result="s"><feDistantLight azimuth="235" elevation="44"/></feSpecularLighting>
<feComposite in="s" in2="d" operator="arithmetic" k2=".45" k3="1"/>
<feColorMatrix type="matrix" values="${tint}"/>
</filter>
<g transform="rotate(${rotate} ${cx} ${cy})"><rect x="${cx - span / 2}" y="${cy - span / 2}" width="${span}" height="${span}" filter="url(#f)"/></g>
</svg>`;
}

/** Returns a URL usable in CSS `background-image` (PNG data URL, or SVG fallback). */
export async function renderFabric(width, height, options = {}) {
  const scale = options.downscale || 2.6; // render small, upscale smoothly
  const pxW = Math.max(480, Math.round(width / scale));
  const pxH = Math.max(320, Math.round(height / scale));
  const svgUrl = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(fabricSVG(pxW, pxH, options))}`;

  try {
    const img = new Image();
    img.src = svgUrl;
    await img.decode();
    const canvas = document.createElement("canvas");
    canvas.width = pxW;
    canvas.height = pxH;
    canvas.getContext("2d").drawImage(img, 0, 0);
    return canvas.toDataURL("image/jpeg", 0.92);
  } catch {
    // Some browsers refuse to export SVG-drawn canvases; use the SVG directly.
    return svgUrl;
  }
}

/** Cache of rendered textures, keyed by tone/size, shared across components. */
const cache = new Map();
export function getFabric(key, width, height, options) {
  if (!cache.has(key)) cache.set(key, renderFabric(width, height, options));
  return cache.get(key);
}
